// SELECCION AUTONOMA: nadie pone 'SI' a mano. Decide por señal comercial + replica la receta de exito por sector.
const days=(f)=>{const s=String(f||'').slice(0,10);if(!s)return 99999;const t=Date.parse(s);return isNaN(t)?99999:Math.floor((Date.now()-t)/86400000);};
const norm=s=>String(s||'').toLowerCase().trim();
const leads=$input.all().map(i=>i.json).filter(l=>l&&l.ID_Lead);
// Sectores CALIENTES: donde ya hubo una respuesta/avance que hizo sentido -> replicar al resto del sector.
const HOT=new Set();for(const l of leads){if(['respondio','agendado','lead_handoff','ganado'].includes(norm(l.Estado)))HOT.add(norm(l.Sector));}
const vivas=['no_contactado','contactado','respondio','agendado','nurturing','lead_handoff'];
const out=[];
for(const l of leads){const est=norm(l.Estado);const man=['si','sí'].includes(norm(l.Investigar_Profundo));const ant=days(l.Ultima_Investigacion);
 if(ant<=7&&!man)continue;                 // investigada hace poco -> no gastar creditos
 if(!vivas.includes(est)&&!man)continue;   // solo cuentas vivas (o override manual)
 let p=0,m='';
 if(est==='agendado'||est==='respondio'){p=100;m='reunion/respuesta: dossier previo a la junta';}
 else if(man){p=95;m='override manual';}
 else if(est==='lead_handoff'){p=90;m='handoff al cierre';}
 else if(est==='contactado'&&ant>=99999){p=80;m='contactada sin dossier';}
 else if(HOT.has(norm(l.Sector))&&ant>=99999){p=70;m='sector caliente: receta de exito';}
 else if(ant>=30){p=40;m='re-investigacion (>30 dias)';}
 else if(ant>=99999){p=30;m='nunca investigada';}
 else continue;
 out.push({...l,_prioridad:p,_motivo:m});}
out.sort((a,b)=>b._prioridad-a._prioridad);
return out.slice(0,8).map(j=>({json:j}));

