let text=''; try{const _b=$json.content||[];const _t=_b.find(x=>x&&x.type==='text');text=_t?_t.text:'';}catch(e){text='';}
text=(text||'').replace(/^```(markdown)?/i,'').replace(/```$/,'').trim();
const l=$('Armar dossier').item.json;
const hoy=$now.toFormat('yyyy-LL-dd');
function sec(n){const m=text.match(new RegExp('###\\s*'+n+'[^\\n]*\\n([\\s\\S]*?)(?=\\n###\\s|$)','i'));return m?m[1].trim():'';}
const conf=(text.match(/CONFIANZA[:\s]*([0-9]{1,3})/i)||[])[1]||70;
let notas=l.Notas||''; notas+=` | investigado ${hoy} (dossier conf ${conf}%)`;
return [{json:{
 inv:{Fecha:hoy,ID_Lead:l.ID_Lead,Empresa:l.Empresa,Sector:l.Sector,
  Resumen:sec('RESUMEN')||text.slice(0,400),
  Dossier_MD:text||'(sin contenido)',
  Riesgos_Clave:sec('RIESGOS'),BusinessCase_ACCES:sec('BUSINESS CASE'),
  Decisores:sec('DECISORES'),Abogado_Diablo:sec('ABOGADO'),
  Siguiente_Paso:sec('SIGUIENTE PASO'),Fuentes:sec('FUENTES'),Confianza:conf},
 ID_Lead:l.ID_Lead,Ultima_Investigacion:hoy,Investigar_Profundo:'no',Notas:notas
}}];
